command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="700500d92442f25002fb707031d7c2ff2cb2052f"
$candidate="05c4f488ed9122b25f0956840967fbde4c2ebc9e"
$built="5c4312c788f4d8dc24ea8ffc4e1bbfb270eb234f"
$branch="work/shell-provider-copyout-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "provider copyout r2 fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before provider copyout r2"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "provider copyout r2 candidate mismatch"}
& git diff --quiet $built $candidate -- app/winui src/base
if($LASTEXITCODE -ne 0){throw "r2 changed product source after accepted Release build"}
$dirty=@(& git status --porcelain=v1 -uall)
if($dirty.Count -ne 0){$dirty|%{Write-Host ("UNEXPECTED_WORKTREE="+$_)};throw "persistent checkout dirty"}
& git switch --detach $candidate
if($LASTEXITCODE -ne 0){throw "provider copyout r2 checkout failed"}
$exe=Join-Path $repo "out\winui\Release\flyExplorer.exe"
if(-not(Test-Path -LiteralPath $exe -PathType Leaf)){throw "provider copyout accepted Release binary missing"}
& python -X utf8 tests\winui\test_shell_provider_copyout_gui.py --configuration Release
if($LASTEXITCODE -ne 0){throw "provider copyout r2 focused GUI failed"}
& git switch main
if($LASTEXITCODE -ne 0){throw "failed to restore main after provider copyout r2"}
& git merge --ff-only origin/main
if($LASTEXITCODE -ne 0){throw "failed to fast-forward main after provider copyout r2"}
Write-Host "SHELL_PROVIDER_COPYOUT_VALIDATION=PASS"
